values
  ('c4271369-abf7-461c-8d3d-69d44d00f1e7', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Mathematical Logic and Proof for Computation', 'Theory of computation is proof-driven. This opening unit makes students fluent in the symbolic language, proof patterns, and formal precision needed for the rest of the course.', 0),
  ('0c368fc3-0cd0-4f16-87e3-22f5424ba892', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'c4271369-abf7-461c-8d3d-69d44d00f1e7', 'subtopic'::public.curated_course_node_type, 'Propositional and predicate logic', 'Students learn how formal statements are built, interpreted, negated, and used as the raw material of specifications and machine models.', 0),
  ('db4f8e02-8219-4ddf-8925-ee1f9c5c4076', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '0c368fc3-0cd0-4f16-87e3-22f5424ba892', 'concept'::public.curated_course_node_type, 'Truth tables and logical equivalence', null, 0),
  ('aab937bf-31a0-4d72-9994-59a92a200c95', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '0c368fc3-0cd0-4f16-87e3-22f5424ba892', 'concept'::public.curated_course_node_type, 'Quantifiers and domains', null, 1),
  ('cc2d551c-6eab-46bb-9e19-1077503a792d', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '0c368fc3-0cd0-4f16-87e3-22f5424ba892', 'concept'::public.curated_course_node_type, 'Formalizing English statements', null, 2),
  ('45bd9de4-172c-465f-aa71-0bb68afb6f0c', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'c4271369-abf7-461c-8d3d-69d44d00f1e7', 'subtopic'::public.curated_course_node_type, 'Proof techniques', 'The goal is to make claims about infinite sets of strings, machines, and languages feel manageable through reusable proof patterns.', 1),
