  ('ea4fa4ad-d38d-4ce7-b2f9-786e25b9a671', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '45bd9de4-172c-465f-aa71-0bb68afb6f0c', 'concept'::public.curated_course_node_type, 'Structural induction', null, 2),
