  ('3254a2d9-e267-4861-94eb-45b59bc02587', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'c4271369-abf7-461c-8d3d-69d44d00f1e7', 'subtopic'::public.curated_course_node_type, 'Sets, relations, and functions', 'These structures give precise vocabulary for languages, transitions, encodings, reductions, and simulations.', 2),
