  ('7def9157-6386-4e7b-a966-a2143026d1a3', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '3254a2d9-e267-4861-94eb-45b59bc02587', 'concept'::public.curated_course_node_type, 'Partial and total functions', null, 2),
  ('0bdfefb2-e728-4f35-8a71-20bd54ffe2d0', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '3254a2d9-e267-4861-94eb-45b59bc02587', 'concept'::public.curated_course_node_type, 'Countability preview', null, 3),
  ('71b4252f-3758-427f-8f53-3f5d2ae2c140', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Alphabets, Strings, Languages, and Formal Models', 'Before studying machines, students need a shared model of what machines read, produce, and recognize. This unit turns computation into a mathematical object.', 1),
  ('06fdd0eb-cbf1-46c0-ba7c-732576b7de82', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '71b4252f-3758-427f-8f53-3f5d2ae2c140', 'subtopic'::public.curated_course_node_type, 'Strings and languages', 'Students learn to treat collections of strings as decision problems, which is the central abstraction of the course.', 0),
  ('362d695f-19a1-470c-8412-17c65753d7ad', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '06fdd0eb-cbf1-46c0-ba7c-732576b7de82', 'concept'::public.curated_course_node_type, 'Alphabets and empty string', null, 0),
  ('aa756246-b02c-4cd8-82ce-a93764d7ee20', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '06fdd0eb-cbf1-46c0-ba7c-732576b7de82', 'concept'::public.curated_course_node_type, 'Concatenation, powers, and Kleene star', null, 1),
  ('102bac71-29c6-493a-bf21-ac49d9b07eec', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '06fdd0eb-cbf1-46c0-ba7c-732576b7de82', 'concept'::public.curated_course_node_type, 'Language operations', null, 2),
  ('d7595ca3-92b7-4641-8767-769bfa194fb8', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '71b4252f-3758-427f-8f53-3f5d2ae2c140', 'subtopic'::public.curated_course_node_type, 'Decision problems and recognizers', 'This frames computation as yes/no classification, making later comparisons between automata, Turing machines, and complexity classes clean.', 1),
  ('bfb354c5-8040-42bc-866f-7f811efefe28', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'd7595ca3-92b7-4641-8767-769bfa194fb8', 'concept'::public.curated_course_node_type, 'Recognition versus decision', null, 0),
  ('886ff263-fab2-4197-a49e-9922c5e97a66', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'd7595ca3-92b7-4641-8767-769bfa194fb8', 'concept'::public.curated_course_node_type, 'Encodings of inputs', null, 1),
  ('b6f397d4-a8db-48fe-961b-f7bc852f24cb', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'd7595ca3-92b7-4641-8767-769bfa194fb8', 'concept'::public.curated_course_node_type, 'Membership questions', null, 2),
  ('6332411f-bba0-47a2-8815-2e170535b3f5', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '71b4252f-3758-427f-8f53-3f5d2ae2c140', 'subtopic'::public.curated_course_node_type, 'Modeling assumptions', 'Students see why simple abstract machines can reveal general truths about all computing devices.', 2),
  ('478c0e25-c4b9-40ea-be97-3f0fa6f2da69', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '6332411f-bba0-47a2-8815-2e170535b3f5', 'concept'::public.curated_course_node_type, 'Finite descriptions', null, 0),
  ('7a16aeb5-ee27-4070-b40a-8db3808a3bde', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '6332411f-bba0-47a2-8815-2e170535b3f5', 'concept'::public.curated_course_node_type, 'Determinism and nondeterminism', null, 1),
  ('aedbda05-1942-4cf4-ba98-84c7996a96d9', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '6332411f-bba0-47a2-8815-2e170535b3f5', 'concept'::public.curated_course_node_type, 'Abstraction versus implementation', null, 2),
  ('1a5a81c8-262d-49e1-bba7-47a9f3329c1d', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Finite Automata', 'Finite automata are the first machine model: limited memory, precise behavior, and enough power to model lexical patterns, protocols, and simple controllers.', 2),
  ('4f1916e6-dc6a-4cb8-bd2c-8899b4968dc7', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '1a5a81c8-262d-49e1-bba7-47a9f3329c1d', 'subtopic'::public.curated_course_node_type, 'Deterministic finite automata', 'DFAs show how computation can be represented as state evolution over an input string.', 0),
  ('9dff069e-7398-47cf-90e6-8daa1a40dba2', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '4f1916e6-dc6a-4cb8-bd2c-8899b4968dc7', 'concept'::public.curated_course_node_type, 'States, alphabet, transition function', null, 0),
  ('9f50b411-442b-41c0-b552-44a45932649e', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '4f1916e6-dc6a-4cb8-bd2c-8899b4968dc7', 'concept'::public.curated_course_node_type, 'Start and accepting states', null, 1),
  ('387afd3f-797c-4d45-a61c-84ffa4dcd108', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '4f1916e6-dc6a-4cb8-bd2c-8899b4968dc7', 'concept'::public.curated_course_node_type, 'Extended transition function', null, 2),
  ('cc28a827-aeef-4c3a-b160-8d9bdcb2da73', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '4f1916e6-dc6a-4cb8-bd2c-8899b4968dc7', 'concept'::public.curated_course_node_type, 'Design from language descriptions', null, 3),
