  ('424d544f-857a-467c-a3ec-5e96711338a1', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'f2217054-b78d-432a-ae39-a33852842e6f', 'concept'::public.curated_course_node_type, 'Equivalence to DFAs', null, 3),
  ('1a9ff73e-2bb7-423d-8b3b-13f6ca5e64fe', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '1a5a81c8-262d-49e1-bba7-47a9f3329c1d', 'subtopic'::public.curated_course_node_type, 'Automata design and invariants', 'Students learn to prove that a machine recognizes exactly the intended language, not merely to draw state diagrams.', 2),
