  ('c903918f-112e-4cdf-b511-916340ef4409', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Regular Languages and Expressions', 'This unit connects machine recognition to algebraic descriptions of patterns, making regularity both operational and syntactic.', 3),
  ('a9949a7d-efb7-406b-9ca0-19d6c227ec5f', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'c903918f-112e-4cdf-b511-916340ef4409', 'subtopic'::public.curated_course_node_type, 'Regular expressions', 'Regular expressions provide a compact language-building notation and connect theory to practical pattern matching.', 0),
  ('747394cc-0100-42a4-a833-e77a90387279', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'a9949a7d-efb7-406b-9ca0-19d6c227ec5f', 'concept'::public.curated_course_node_type, 'Union, concatenation, star', null, 0),
