  ('dc26b687-3927-4a2a-b93f-a1d945d86653', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'a9949a7d-efb7-406b-9ca0-19d6c227ec5f', 'concept'::public.curated_course_node_type, 'Regex-to-NFA construction', null, 2),
  ('78cf4064-fcdc-4a8d-9b67-be08e3828091', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'c903918f-112e-4cdf-b511-916340ef4409', 'subtopic'::public.curated_course_node_type, 'Closure properties', 'Closure gives a toolkit for building new regular languages from known ones while preserving recognizability.', 1),
  ('6d9e0427-d085-45de-98af-b62c123a2682', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '78cf4064-fcdc-4a8d-9b67-be08e3828091', 'concept'::public.curated_course_node_type, 'Union, intersection, complement', null, 0),
  ('4512344f-6f10-42ad-8301-f8063779dfcd', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '78cf4064-fcdc-4a8d-9b67-be08e3828091', 'concept'::public.curated_course_node_type, 'Difference and reversal', null, 1),
  ('bf530b88-253b-415d-8816-c886d136a25f', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '78cf4064-fcdc-4a8d-9b67-be08e3828091', 'concept'::public.curated_course_node_type, 'Homomorphisms and inverse homomorphisms', null, 2),
  ('8e013d5a-df5d-4a06-b144-850cbf30123c', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'c903918f-112e-4cdf-b511-916340ef4409', 'subtopic'::public.curated_course_node_type, 'Equivalence of representations', 'Students learn that DFAs, NFAs, and regular expressions describe exactly the same class of languages.', 2),
  ('682bcf29-0460-44ca-a004-9261e0d7e2c7', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '8e013d5a-df5d-4a06-b144-850cbf30123c', 'concept'::public.curated_course_node_type, 'Kleene theorem', null, 0),
  ('a1c2fe63-f657-452e-9048-eb712dd37282', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '8e013d5a-df5d-4a06-b144-850cbf30123c', 'concept'::public.curated_course_node_type, 'State elimination', null, 1),
  ('df5db278-d381-4c55-94f7-ba48d737e193', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '8e013d5a-df5d-4a06-b144-850cbf30123c', 'concept'::public.curated_course_node_type, 'Conversion workflows', null, 2),
  ('e83cecf6-8205-487a-b44e-9549d60c30ab', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Nonregularity and Lower Bounds for Finite Memory', 'Not every pattern can be recognized with finite memory. This unit teaches students how to prove impossibility, a central habit of theoretical CS.', 4),
  ('7b798e99-d48e-4c0a-9f29-3caaa548619c', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'e83cecf6-8205-487a-b44e-9549d60c30ab', 'subtopic'::public.curated_course_node_type, 'Pumping lemma for regular languages', 'The pumping lemma gives a reusable contradiction method for showing that finite automata cannot remember enough.', 0),
  ('dc9a7a72-0c23-447d-a389-fbfd692e9ebc', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '7b798e99-d48e-4c0a-9f29-3caaa548619c', 'concept'::public.curated_course_node_type, 'Choosing adversarial strings', null, 0),
  ('f5191550-695f-4437-a9b2-8ddae1745259', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '7b798e99-d48e-4c0a-9f29-3caaa548619c', 'concept'::public.curated_course_node_type, 'Quantifier order', null, 1),
  ('a2b644e7-0066-426d-a904-6dbc4165cf96', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '7b798e99-d48e-4c0a-9f29-3caaa548619c', 'concept'::public.curated_course_node_type, 'Decomposition arguments', null, 2),
  ('a2804c2a-715d-40ee-9f3c-c7344e3910a2', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'e83cecf6-8205-487a-b44e-9549d60c30ab', 'subtopic'::public.curated_course_node_type, 'Myhill-Nerode theorem', 'Myhill-Nerode reveals regularity through distinguishable prefixes and gives a sharper view of minimal memory.', 1),
  ('3260889f-6e67-4de2-b36d-eba36e26d2c8', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'a2804c2a-715d-40ee-9f3c-c7344e3910a2', 'concept'::public.curated_course_node_type, 'Right congruence', null, 0),
  ('fbcc62c9-8fc0-4d2c-8d44-72ae59febbe1', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'a2804c2a-715d-40ee-9f3c-c7344e3910a2', 'concept'::public.curated_course_node_type, 'Distinguishing extensions', null, 1),
  ('52fee8e4-8768-472e-8079-2ba69d1e77c2', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'a2804c2a-715d-40ee-9f3c-c7344e3910a2', 'concept'::public.curated_course_node_type, 'Minimal DFA states', null, 2),
  ('2a655ea9-32e8-4006-b906-72160a8c5a13', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'e83cecf6-8205-487a-b44e-9549d60c30ab', 'subtopic'::public.curated_course_node_type, 'Finite-memory lower bounds', 'Students learn to translate intuitive memory limitations into formal state-count arguments.', 2),
  ('79a47ca6-75a1-4deb-99e7-e73ff8894b5b', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '2a655ea9-32e8-4006-b906-72160a8c5a13', 'concept'::public.curated_course_node_type, 'Crossing sequences preview', null, 0),
  ('3bc22ef6-045f-4332-97d1-d1eee6838413', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '2a655ea9-32e8-4006-b906-72160a8c5a13', 'concept'::public.curated_course_node_type, 'Fooling sets', null, 1),
  ('5228d23e-f63f-4cd2-829d-a1308cbe11a5', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '2a655ea9-32e8-4006-b906-72160a8c5a13', 'concept'::public.curated_course_node_type, 'Protocol/state examples', null, 2),
  ('3592ee6c-cda3-4aa9-beb1-0c929416191f', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Context-Free Grammars and Languages', 'Context-free grammars model recursive structure, such as nested parentheses and programming-language syntax, which finite automata cannot handle.', 5),
  ('9a6bc6f3-3ef3-4e03-85a4-729dcffe9ca4', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '3592ee6c-cda3-4aa9-beb1-0c929416191f', 'subtopic'::public.curated_course_node_type, 'Grammar definitions and derivations', 'Students learn how recursive production rules generate languages and parse structural patterns.', 0),
  ('67e3c505-a8af-48e0-9e62-82fdc6ffac2d', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '9a6bc6f3-3ef3-4e03-85a4-729dcffe9ca4', 'concept'::public.curated_course_node_type, 'Variables, terminals, productions', null, 0),
