  ('ca539397-1172-4495-8cd8-f9c08d33090c', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '9a6bc6f3-3ef3-4e03-85a4-729dcffe9ca4', 'concept'::public.curated_course_node_type, 'Parse trees', null, 2),
  ('49369af8-b0ad-4a14-a2d5-fe5c3f87357e', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '3592ee6c-cda3-4aa9-beb1-0c929416191f', 'subtopic'::public.curated_course_node_type, 'Grammar design', 'The point is to move from informal recursive descriptions to exact grammars that generate all and only desired strings.', 1),
  ('fb931372-fad2-48d8-945a-5ad7f46633b3', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '49369af8-b0ad-4a14-a2d5-fe5c3f87357e', 'concept'::public.curated_course_node_type, 'Balanced structures', null, 0),
