  ('4f4ee255-4bb4-4927-ab7d-8d500953ef50', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Pushdown Automata and Parsing Connections', 'Pushdown automata add a stack to finite control. This gives the first concrete model of unbounded but disciplined memory.', 6),
  ('45b44d03-685e-491d-820f-269469ccd0ad', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '4f4ee255-4bb4-4927-ab7d-8d500953ef50', 'subtopic'::public.curated_course_node_type, 'PDA mechanics', 'Students see how stacks make nested and recursive language recognition possible.', 0),
