  ('a98f93eb-5cc0-48d1-a251-23a903b68374', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '4f4ee255-4bb4-4927-ab7d-8d500953ef50', 'subtopic'::public.curated_course_node_type, 'Equivalence with CFGs', 'The equivalence between PDAs and CFGs ties generative syntax to operational recognition.', 1),
  ('ccf8326d-1d35-43a6-a864-f2781ba9d0d7', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'a98f93eb-5cc0-48d1-a251-23a903b68374', 'concept'::public.curated_course_node_type, 'CFG-to-PDA construction', null, 0),
