  ('92a1c291-fb3a-4d01-9db9-e03e2569d980', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Non-Context-Free Languages', 'This unit extends impossibility proof skills to recursive structures and shows the limits of a single stack.', 7),
