  ('396ae8cc-2846-4505-9225-a59a290af741', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '7d46d9b7-2247-4e45-8869-c09fb88cd199', 'concept'::public.curated_course_node_type, 'Closure under union and concatenation', null, 0),
