  ('6db1d74f-9c30-4422-b9ed-060838323a83', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Turing Machines and Equivalent Models', 'Turing machines are the course''s general model of computation. They let students reason about what is computable independent of any particular hardware or language.', 8),
  ('0d8775ab-3219-4716-bdbe-59c086862b6e', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '6db1d74f-9c30-4422-b9ed-060838323a83', 'subtopic'::public.curated_course_node_type, 'Turing machine definitions', 'Students learn the formal parts of a machine powerful enough to capture general algorithms.', 0),
  ('fa8c1b0f-3fc4-4db2-90fe-8e4aa0565841', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '0d8775ab-3219-4716-bdbe-59c086862b6e', 'concept'::public.curated_course_node_type, 'Tape, head, states, transition function', null, 0),
