  ('b290f68d-bcd9-4851-886b-47d7271b713c', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '6db1d74f-9c30-4422-b9ed-060838323a83', 'subtopic'::public.curated_course_node_type, 'Variants and robustness', 'Different machine variants all compute the same class of functions, which supports the Church-Turing thesis.', 1),
