  ('d928e136-c91f-4177-98a2-67d4e41e986f', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '4169d179-5d02-4658-9e21-e68eca554457', 'concept'::public.curated_course_node_type, 'Binary/string encodings', null, 0),
