  ('c51fe8de-3762-4561-a448-7bcf7879bca6', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '4169d179-5d02-4658-9e21-e68eca554457', 'concept'::public.curated_course_node_type, 'Simulation overhead', null, 2),
  ('b614138d-6a30-45ae-9c95-008dec18b90e', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Decidability, Recognizability, and the Halting Problem', 'This unit establishes the boundary between problems solvable by algorithms and problems that no algorithm can decide.', 9),
