  ('8f4b82ae-a815-4dd3-b59d-77412f02daa6', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '2fc2a2cd-0aff-4517-a70a-51201a056570', 'concept'::public.curated_course_node_type, 'Deciders versus recognizers', null, 0),
