  ('91be9a44-173b-49b5-bbc7-26802e4dde8e', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '3a312a57-442a-43de-8d2d-1d7699a9f350', 'concept'::public.curated_course_node_type, 'Self-reference', null, 0),
