  ('eae17673-7f11-4691-9c13-b246b609f925', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '7883f1ac-2f11-44c1-be23-2e2f693ec0c6', 'concept'::public.curated_course_node_type, 'Emptiness and equivalence for TMs', null, 0),
  ('b8bd892f-5d18-4d2c-87a4-530947b3a7fe', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '7883f1ac-2f11-44c1-be23-2e2f693ec0c6', 'concept'::public.curated_course_node_type, 'Post correspondence problem overview', null, 1),
  ('4ceacacd-29ac-42ba-a6e1-9963fae651a7', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '7883f1ac-2f11-44c1-be23-2e2f693ec0c6', 'concept'::public.curated_course_node_type, 'Rice''s theorem', null, 2),
  ('c25bc0f4-38b2-4cf5-a7f7-2620fc1edf6c', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Reducibility and Undecidability Proofs', 'Reductions are the language of comparison: they show that solving one problem would solve another known-hard problem.', 10),
