  ('f370f3b0-c5bc-49d5-bba1-dd9106c764d9', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'fe11e72a-fa09-4944-a3bb-3541f6aa697d', 'concept'::public.curated_course_node_type, 'Computable transformations', null, 0),
