  ('72744da7-dca1-4c18-a6a9-784c28e7ce52', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'fe11e72a-fa09-4944-a3bb-3541f6aa697d', 'concept'::public.curated_course_node_type, 'Source problem choice', null, 2),
  ('3bfa8ac8-4557-4470-82f2-f13711a08aed', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'c25bc0f4-38b2-4cf5-a7f7-2620fc1edf6c', 'subtopic'::public.curated_course_node_type, 'Turing reductions', 'Oracle-style reductions broaden the idea of solving one problem using another as a subroutine.', 1),
  ('5d57a8d2-7516-489c-be25-e86c3e72c347', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '3bfa8ac8-4557-4470-82f2-f13711a08aed', 'concept'::public.curated_course_node_type, 'Oracle machines', null, 0),
