  ('5e89b0df-e1d3-4e73-a717-cc5843542172', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '3bfa8ac8-4557-4470-82f2-f13711a08aed', 'concept'::public.curated_course_node_type, 'Relative computability', null, 2),
  ('8183f75e-a64d-4fbb-acba-9a9e8f255aac', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'c25bc0f4-38b2-4cf5-a7f7-2620fc1edf6c', 'subtopic'::public.curated_course_node_type, 'Proof design patterns', 'The point is to make reductions feel like engineering a logical trap: any solver for the target would break a known impossibility.', 2),
  ('8e1ee93f-3095-4fcb-9e29-6a38ce412e18', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '8183f75e-a64d-4fbb-acba-9a9e8f255aac', 'concept'::public.curated_course_node_type, 'Machine construction', null, 0),
