  ('4611d377-3ff7-4e2d-9d67-7f57cb1030ca', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Time Complexity and Efficient Computation', 'After computability asks what can be solved at all, complexity asks what can be solved with feasible resources.', 11),
  ('77e125ec-0d19-40e5-98e1-5b9a0c33eb5e', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '4611d377-3ff7-4e2d-9d67-7f57cb1030ca', 'subtopic'::public.curated_course_node_type, 'Asymptotic time on machine models', 'Students learn to measure algorithms in a model-independent way while respecting simulation costs.', 0),
  ('4cea5d8f-25ac-45af-8ebc-a188758cd49a', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '77e125ec-0d19-40e5-98e1-5b9a0c33eb5e', 'concept'::public.curated_course_node_type, 'Big-O, little-o, omega', null, 0),
