  ('5a8ad111-d8c5-44a6-9184-6df0dad1a4fb', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '77e125ec-0d19-40e5-98e1-5b9a0c33eb5e', 'concept'::public.curated_course_node_type, 'Polynomial robustness', null, 2),
  ('be21e391-7c24-4ac0-922a-9764acff7bd8', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '4611d377-3ff7-4e2d-9d67-7f57cb1030ca', 'subtopic'::public.curated_course_node_type, 'Class P', 'P formalizes efficient deterministic computation and becomes the baseline for tractability.', 1),
