  ('1eca3bf7-d5ed-47bf-97c1-f2b0969e69f6', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Nondeterminism, NP, and NP-Completeness', 'NP-completeness is the course''s major bridge to algorithms, optimization, cryptography, and practical intractability.', 12),
  ('695caf71-41f2-4a16-85dd-246f293d621f', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '1eca3bf7-d5ed-47bf-97c1-f2b0969e69f6', 'subtopic'::public.curated_course_node_type, 'Class NP', 'Students learn NP as efficiently verifiable search, not just as nondeterministic guessing.', 0),
