  ('398e3bbb-53f8-43af-92b6-b766d91bce52', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Space Complexity and Hierarchy Theorems', 'Space complexity reveals that memory can be a more subtle resource than time and introduces classes central to modern theory.', 13),
