  ('658d7c3e-9769-43cb-b3a2-25294abbb3f1', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '1f60e971-0e40-45df-b556-22865fe25648', 'concept'::public.curated_course_node_type, 'TQBF/QBF', null, 0),
