  ('9d2ded39-7fd4-4e57-b9b5-4c682abfd73e', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '3f6a78f4-73b0-4001-8708-e99a10558a25', 'concept'::public.curated_course_node_type, 'Space hierarchy theorem', null, 0),
