  ('2b49c93b-7b7a-4e26-b888-81486455cb00', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '3f6a78f4-73b0-4001-8708-e99a10558a25', 'concept'::public.curated_course_node_type, 'Complete problems as landmarks', null, 2),
  ('f1a9239e-3279-4470-8769-ecee15888f03', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Randomized, Counting, and Advanced Complexity', 'A world-class theory course should show how randomness, counting, interaction, and approximation reshape the landscape beyond P and NP.', 14),
  ('12f87a51-a3a5-496a-8f70-e91fbed21f90', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'f1a9239e-3279-4470-8769-ecee15888f03', 'subtopic'::public.curated_course_node_type, 'Randomized computation', 'Students learn how algorithms can use random choices and how complexity classes track allowable error.', 0),
  ('00f6b50f-a42a-47b4-97ef-0b34fc73fa40', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '12f87a51-a3a5-496a-8f70-e91fbed21f90', 'concept'::public.curated_course_node_type, 'RP, coRP, BPP', null, 0),
