  ('5aeee8c0-0945-4c69-a850-bc7147818da6', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '6cb1f42e-29df-4141-8b00-88bf9f01ca58', 'concept'::public.curated_course_node_type, '#P', null, 0),
