  ('d641a8a7-affe-4c75-b70b-a7cef1f3a10a', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '0e88fcc9-08f3-45e1-afa5-a350c9526064', 'concept'::public.curated_course_node_type, 'IP and AM intuition', null, 0),
  ('6aa1f5ec-22a1-4b80-ab84-c88e82d92041', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '0e88fcc9-08f3-45e1-afa5-a350c9526064', 'concept'::public.curated_course_node_type, 'PCP theorem statement', null, 1),
  ('a3736eb8-da55-409a-a689-29a31351588a', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '0e88fcc9-08f3-45e1-afa5-a350c9526064', 'concept'::public.curated_course_node_type, 'Hardness of approximation', null, 2),
  ('87b7addb-9dfc-4a40-895e-2c665e5b524b', '57e34d17-dbac-43d4-8c1c-0778df6956b0', null, 'topic'::public.curated_course_node_type, 'Theory in Modern CS: Algorithms, Languages, Cryptography, and Verification', 'The final unit connects formal theory to the broader CS curriculum so students see computation theory as a living toolkit, not a sealed-off subject.', 15),
  ('e2f63ec4-a78e-458a-bc69-01b93e8c4ad3', '57e34d17-dbac-43d4-8c1c-0778df6956b0', '87b7addb-9dfc-4a40-895e-2c665e5b524b', 'subtopic'::public.curated_course_node_type, 'Algorithmic hardness and approximation', 'Students learn how theory explains why some optimization problems resist exact efficient algorithms.', 0),
  ('89f8b109-829f-4e5a-83e3-f47c2ada1cfc', '57e34d17-dbac-43d4-8c1c-0778df6956b0', 'e2f63ec4-a78e-458a-bc69-01b93e8c4ad3', 'concept'::public.curated_course_node_type, 'Approximation ratios', null, 0),
